export default {async fetch(request){const url=new URL(request.url),path=url.pathname;if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405});if(path==='/app.css')return reply(CSS,'text/css; charset=utf-8');if(path==='/app.js')return reply(APP,'application/javascript; charset=utf-8');if(path==='/favicon.svg')return reply(ICON,'image/svg+xml');if(path==='/'||path==='/predictions'||path==='/index.html')return reply(HTML,'text/html; charset=utf-8');if(path.startsWith('/api/')){const r=await fetch(new Request(new URL(path+url.search,BASE),request));const h=new Headers(r.headers);h.set('Cache-Control','no-store');h.set('X-Content-Type-Options','nosniff');return new Response(r.body,{status:r.status,headers:h})}return new Response('Not found',{status:404})}};